pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic normalized values
    let progress = step_index as f64 / total_items as f64;
    let r_frac = post_residual as f64 / bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    let fit_factor = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);

    // Start with the residual fraction as baseline
    let mut score = r_frac;

    // Penalty for residual growing over time
    score += r_frac * r_frac * progress;

    // Penalise bins with few fitting options
    score += (1.0 - fit_factor) * r_frac * r_frac * progress;

    // Extra cost if residual exceeds mean
    if r_frac > mean_frac {
        score += (r_frac - mean_frac) * (1.0 - progress);
    }

    // Reward if residual can hold the next item
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        if r_frac >= next_norm {
            score -= (1.0 - r_frac) * (1.0 - progress) * ((open_bins_count as f64) + 1.0);
        }
    }

    // Tight‑fit bonus: reward bins that leave little space after placement
    let tight_threshold = 0.1; // 10% of capacity
    if r_frac <= tight_threshold {
        score -= 0.5 * (1.0 - r_frac);
    }

    // Waste penalty: heavily penalise bins that still hold >80% empty
    let waste_threshold = 0.8;
    if r_frac >= waste_threshold {
        score += (r_frac - waste_threshold) * 2.0;
    }

    // Open‑bin pressure: if many bins are open, discourage using already sparse bins
    let open_pressure = 5;
    if open_bins_count > open_pressure && r_frac > 0.5 {
        score += (r_frac - 0.5) * 1.5;
    }

    // Prefer bins whose residual is below the mean residual
    if r_frac < mean_frac {
        score -= (mean_frac - r_frac) * 1.0;
    }

    // Large‑item bias: if the item is >75% of the bin, favour bins with very low residual
    let large_item_cut = 0.75;
    if fit_ratio >= large_item_cut && r_frac > 0.25 {
        score += (r_frac - 0.25) * 1.5;
    }

    // Single‑fit penalty: if only this bin can hold the item and it’s still too sparse
    if fitting_bins_count == 1 && r_frac > 0.4 {
        score += (r_frac - 0.4) * 2.0;
    }

    score
}

