pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress in the stream [0,1]
    let progress = step_index as f64 / total_items as f64;

    // Residual after placing the item
    let residual_after = post_residual as f64;
    let residual_before = (bin_residual - item_size) as f64;

    // Fractional residuals relative to capacity
    let frac_after = residual_after / bin_capacity as f64;
    let frac_before = residual_before / bin_capacity as f64;

    // Early‑stream penalty for loose fits – weight rises early, tapers late
    let residual_weight = 1.0 + (1.0 - progress).powi(3) * 2.0;

    // Base score: weighted residual after placement (lower is better)
    let mut score = residual_weight * residual_after;

    // Penalise bins whose residual after placement deviates above the mean
    let mean_diff = residual_after - mean_residual;
    score += mean_diff * 0.5 * progress;

    // Look‑ahead: favour bins that can accommodate the next item
    let next_fit = next_item_size as i32 - post_residual as i32;
    if next_fit > 0 {
        // Not enough space for next item – small penalty proportional to the gap
        score += (next_fit as f64) * 0.3;
    } else {
        // Can fit next item – small reward
        score -= (-next_fit as f64) * 0.2;
    }

    // Encourage bins that are more full relative to capacity
    let fullness = 1.0 - frac_after;
    score -= fullness * 0.4;

    // If many open bins, slightly favour re‑use
    if open_bins_count > 8 {
        score += 1.0;
    }

    // If many fitting bins exist, reward tighter residual
    if fitting_bins_count > 5 {
        score -= 0.5;
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer a new bin only when no fits or the score is unacceptably high
        if fitting_bins_count == 0 || score > 25.0 {
            score = 0.0; // open a new bin
        } else {
            // penalise opening a new bin if a better fit exists
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Residual ratios before and after placement
    let before_ratio = bin_residual as f64 / bin_capacity as f64;
    let after_ratio = post_residual as f64 / bin_capacity as f64;

    // Dynamic weight that favors tighter packing early on
    let weight = 1.0 + (1.0 - progress).powi(2) * 2.0;

    // Base score: weighted residual after placement
    let mut score = weight * post_residual as f64;

    // Penalise deviation from the mean residual
    let mean_diff = post_residual as f64 - mean_residual;
    score += mean_diff * mean_diff * 0.05 * progress;

    // Look‑ahead based on the next item
    let next_gap = next_item_size as i32 - post_residual as i32;
    if next_gap <= 0 {
        // Next item fits – reward with a diminishing penalty
        score -= (-next_gap as f64).powf(0.5) * 0.15;
    } else {
        // Not enough space – small penalty that grows sub‑linearly
        score += (next_gap as f64).powf(0.6) * 0.25;
    }

    // Reward bins that were tight before placement
    if bin_residual == item_size {
        // Perfect fit
        score -= 5.0;
    } else if before_ratio < 0.2 {
        score -= 2.0;
    } else if before_ratio > 0.8 {
        score += 3.0;
    }

    // Encourage tighter residuals when many bins can fit
    if fitting_bins_count > 6 {
        score -= after_ratio * 0.5;
    }

    // Penalise large waste early in the stream
    if after_ratio > 0.9 {
        score += after_ratio * 0.3;
    }

    // If many bins are open, discourage opening more
    if open_bins_count > 15 {
        score += 2.0;
    }

    // Prefer a new bin only when no fits exist or the fit is very poor
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // open a new bin
        } else if score > 25.0 {
            score = 0.0; // poor fit – still open a new bin
        } else {
            // Slight penalty for opening a new bin when a better fit exists
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
