    let progress = step_index as f64 / total_items as f64;

    // Weight that rises early, tapers late; encourages tighter fits early
    let residual_weight = 1.0 + (1.0 - progress).powi(3) * 1.8;

    // Base score: weighted residual after placement (lower is better)
    let mut score = residual_weight * post_residual as f64;

    // Penalise bins whose post‑residual deviates above the mean
    let mean_diff = post_residual as f64 - mean_residual;
    score += mean_diff * 0.4 * progress;

    // Look‑ahead: favour bins that can accommodate the next item
    let next_fit = next_item_size as i32 - post_residual as i32;
    if next_fit > 0 {
        // Not enough space for next item – small penalty
        score += (next_fit as f64) * 0.25;
    } else {
        // Can fit next item – small reward
        score -= (-next_fit as f64) * 0.15;
    }

    // If many open bins, slightly favour re‑use
    if open_bins_count > 7 {
        score += 1.2;
    }

    // If many fitting bins exist, reward tighter residual
    if fitting_bins_count > 4 {
        score -= 0.6;
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer a new bin only when no fits or the score is unacceptably high
        if fitting_bins_count == 0 || score > 30.0 {
            score = 0.0; // open a new bin
        } else {
            // penalise opening a new bin if a better fit exists
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress
    let progress = step_index as f64 / total_items as f64;

    // Normalised residual after placement
    let r = post_residual as f64 / bin_capacity as f64;

    // Fraction of open bins that can still fit the item
    let fit_factor = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);

    // Normalised averages
    let mean_norm = mean_residual / bin_capacity as f64;
    let item_norm = item_size as f64 / bin_capacity as f64;
    let next_norm = if next_item_size > 0 {
        next_item_size as f64 / bin_capacity as f64
    } else {
        0.0
    };

    // --- Core scoring -------------------------------------------------------
    let mut score = r; // base residual cost

    // Quadratic penalty for residuals that grow as we progress
    score += r * r * progress * 0.9;

    // Penalise bins that are among the few remaining fits
    score += (1.0 - fit_factor) * r * r * progress * 0.55;

    // Extra penalty if residual exceeds mean by a margin
    if r > mean_norm + 0.05 {
        score += (r - mean_norm) * open_bins_count as f64 * progress * 0.12;
    }

    // Reward residuals close to the item size (minimal waste)
    let diff_item = (r - item_norm).abs();
    score -= diff_item * (1.0 - progress) * 0.8;

    // Look‑ahead: if the residual can still fit the next item, reward
    if next_item_size > 0 && r >= next_norm {
        let next_residual = r - next_norm;
        score -= (1.0 - next_residual) * (1.0 - progress) * (open_bins_count as f64 + 1.0) * 0.6;
    } else if next_item_size > 0 && r < next_norm {
        // Penalty if we would waste space that could fit the next item
        score += (next_norm - r) * (1.0 - progress) * 0.4;
    }

    // Slight reward for bins whose residual is in the middle range (≈0.5 of capacity)
    if r > 0.45 && r < 0.55 {
        score -= 0.05;
    }

    // --- New‑bin logic -------------------------------------------------------
    if bin_residual == bin_capacity {
        // Prefer a new bin when the average residual is high and few bins are open
        if mean_norm > 0.85 && open_bins_count <= 3 {
            score -= 0.5;
        } else if fitting_bins_count == 0 {
            // No other fit – must open
            score -= 0.3;
        } else {
            // Opening a new bin is likely a poor fit
            score += 0.25;
        }
    }

    // --- Early‑stream caution ------------------------------------------------
    if progress < 0.15 && r < 0.02 {
        // Avoid over‑packing too early when residual is tiny
        score += 0.18;
    }

    score
}
